package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoRangeAssemblyTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun propose(text:String,clip:VideoSegment=VideoSegment(1000,9000))=VideoRangeAssembly.propose(listOf(clip),0,text)
 private fun rejected(text:String,clip:VideoSegment=VideoSegment(1000,9000)){assertTrue(text,runCatching{propose(text,clip)}.isFailure)}
 @Test fun enteredOrderAndIntentionalOverlapAndRepeatsStayExact(){val result=propose("5, 7\n1.100, 2.250\n5, 7\n6, 8");assertEquals(listOf(5000L to 7000L,1100L to 2250L,5000L to 7000L,6000L to 8000L),result.map{it.startMs to it.endMs})}
 @Test fun whitespaceCrLfAndBlankRowsAreAllowed(){assertEquals(propose("1,2\n3,4"),propose(" \r\n 1 , 2 \r\n\r\n3,4\r\n"))}
 @Test fun strictNumbersAndTwoColumnRowsRejectAmbiguity(){for(text in listOf("", "1", "1,2,3", "1;2", "1 --> 2", "1:00,2:00", "1e0,2", "NaN,2", "-1,2", "+1,2", "1.0001,2", "1,Infinity", "1,,2", "1,", "1,2147484"))rejected(text)}
 @Test fun outOfClipReversedAndEmptyRangesAreRefused(){for(text in listOf("0,2","1,9.001","4,3","2,2"))rejected(text)}
 @Test fun minimumPlaybackSpanAccountsForSpeed(){for(speed in listOf(.5f,1f,1.5f,2f)){val clip=VideoSegment(0,5000,speed=speed);val minimum=(100*speed).toLong();val good=String.format(java.util.Locale.ROOT,"0,%.3f",minimum/1000.0);assertEquals(100000L,propose(good,clip).single().durationUs);rejected(String.format(java.util.Locale.ROOT,"0,%.3f",(minimum-1)/1000.0),clip)}}
 @Test fun boundedTextAndLineCounts(){assertEquals(100,propose(List(100){"1,2"}.joinToString("\n")).size);rejected(List(101){"1,2"}.joinToString("\n"));rejected(" ".repeat(16001));assertTrue(runCatching{VideoRangeAssembly.propose(listOf(VideoSegment(0,5000)),1,"1,2")}.isFailure)}
 @Test fun otherClipsAndAllNonRangeMetadataRemainUnchanged(){val clip=VideoSegment(1000,9000,speed=1.5f,volume=.4f,title="Take",fadeEdges=true,audioFade=true,grade=VideoGrade(warmth=.2f),layout=VideoLayout(),captionSourceUri="content://synthetic/subtitles");val left=VideoSegment(0,1000);val right=VideoSegment(9000,10000);val result=VideoRangeAssembly.propose(listOf(left,clip,right),1,"5,7\n2,4");assertSame(left,result.first());assertSame(right,result.last());assertEquals(clip.copy(startMs=5000,endMs=7000),result[1]);assertEquals(clip.copy(startMs=2000,endMs=4000),result[2])}
 @Test fun captionsUseSourceIntersectionsAndKeepProvenance(){val cues=listOf(VideoCaption(500,1500,"cross start"),VideoCaption(1500,2000,"inside"),VideoCaption(2000,3000,"edge"),VideoCaption(7000,8000,"later"));val clip=VideoSegment(1000,9000,captions=cues,captionSourceUri="content://synthetic/subtitles");val result=propose("1,2\n7,8\n1,2",clip);assertEquals(cues.take(2),result[0].captions);assertEquals(listOf(cues.last()),result[1].captions);assertEquals(result[0],result[2]);assertTrue(result.all{it.captionSourceUri==clip.captionSourceUri})}
 @Test fun clipAndCueExplosionLimitsRefuseBeforeApplying(){val clip=VideoSegment(0,5000);assertTrue(runCatching{VideoRangeAssembly.propose(List(1000){clip},0,"0,1\n1,2")}.isFailure);val cues=List(20){VideoCaption(it*100L,it*100L+100,"X")};val captioned=clip.copy(captions=cues);assertTrue(runCatching{propose(List(51){"0,2"}.joinToString("\n"),captioned)}.isFailure)}
 @Test fun expandedCaptionTextBudgetIsChecked(){val clip=VideoSegment(0,5000,captions=List(4){VideoCaption(it*100L,it*100L+100,"x".repeat(240))});assertTrue(runCatching{propose(List(67){"0,1"}.joinToString("\n"),clip)}.isFailure)}
 @Test fun wholeClipListIsAnHonestNoOp(){val clip=VideoSegment(1000,9000);assertEquals(listOf(clip),propose("1,9",clip));val r=VideoBatchReview(listOf(clip),null);val d=Any();r.open(d);r.propose(d,listOf(clip));assertTrue(runCatching{r.apply(d,VideoEditProject(10000).also{it.restore(listOf(clip))}){}}.isFailure);assertTrue(r.isClosed)}
 private fun batchFixture():Triple<HonorableVideoEditorActivity,AlertDialog,VideoBatchReview>{val a=activity();val p=get(a,"project")as VideoEditProject;val d=dialog();val r=VideoBatchReview(p.segments,p.soundtrack);r.open(d);r.propose(d,VideoRangeAssembly.propose(p.segments,0,"3,4\n0,1\n3,4"));set(a,"batchReviewRequest",r);set(a,"batchReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return Triple(a,d,r)}
 @Test fun actualApprovalAppliesOnceWithOneUndoAndExistingMusic(){val(a,d,r)=batchFixture();val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;val review=capture(a);assertEquals(true,call(a,"commitBatchReview",d,r,review));assertEquals(listOf(3000L,0L,3000L),p.segments.map{it.startMs});assertSame(music,p.soundtrack);assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo);assertEquals(false,call(a,"commitBatchReview",d,r,review));assertTrue(p.canRedo)}
 @Test fun staleSessionSourceAndTimelineRejectAssembly(){for(flag in listOf("pause","source","duration","generation","mode","range","recovery","busy")){val(a,d,r)=batchFixture();val p=get(a,"project")as VideoEditProject;val before=p.segments;val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"generation"->set(a,"captionReviewGeneration",review.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"range"->set(a,"selectedClip",1);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertEquals(flag,false,call(a,"commitBatchReview",d,r,review));assertSame(before,p.segments);assertFalse(p.canUndo)}}
 @Test fun oldOrInvisibleDialogCannotApplyOrConsumeNewApproval(){for(flag in listOf("hidden","untracked","old")){val(a,d,r)=batchFixture();val review=capture(a);when(flag){"hidden"->showing(d,false);"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());else->set(a,"batchReviewDialog",dialog())};assertEquals(false,call(a,"commitBatchReview",d,r,review));if(flag=="old")assertTrue(r.owns(d));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun existingDraftCodecRetainsRangeOrderSourceAndCaptionTiming(){val result=propose("5,7\n1,2\n5,7");val draft=VideoDraft(10000,result,1,1000,1000,2000);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),10000))}
 @Test fun pausedEntryReturnsBeforeAnyInputWidgets(){val a=activity();set(a,"workspaceActive",false);call(a,"batchEdit",VideoBatchTool.SOURCE_RANGE_LIST);assertNull(get(a,"batchReviewRequest"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}
}
